"use server";

import { redirect } from "next/navigation";
import { revalidatePath } from "next/cache";
import type { User } from "@prisma/client";
import { z } from "zod";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";
import { requireArea } from "./rbac";
import { GAME_FAMILIES } from "./games";
import { getSettingBool, getSettingInt } from "./settings";
import { emailVerificationError } from "./email-verification";
import {
  placeGameOrder,
  gameOrderQuote,
  GameOrderError,
  type GameOrderIntent,
  type GameOrderPrice,
} from "./game-order";
import { walletSplit } from "./wallet-split";
import { createGameOrderCheckout, type EmbeddedCheckout } from "./stripe";

/**
 * Game servers as a distinct product. A `GamePlan` is one pricing tier for one
 * game (Minecraft 2 GB / 10 slots, etc). Admins (billing area) manage the
 * catalogue; customers order a tier, which provisions a VM sized by the tier's
 * base VPS Plan running the game's OsTemplate image.
 *
 * This module owns:
 *   - adminSaveGamePlan / adminToggleGamePlan / adminDeleteGamePlan (CRUD)
 *   - orderGameServer (customer deploy) — mirrors the VPS deploy path in
 *     lib/actions.ts payAndDeploy / lib/order.ts placeOrder.
 */

type Result = { error?: string; ok?: boolean };

// ---------- Admin CRUD ----------

const planSchema = z.object({
  id: z.string().optional(),
  gameFamily: z.enum(GAME_FAMILIES),
  name: z.string().min(2).max(80),
  ramMB: z.coerce.number().int().min(256).max(262144),
  cpuCores: z.coerce.number().int().min(1).max(64),
  diskGB: z.coerce.number().int().min(1).max(4096),
  slots: z.coerce.number().int().min(1).max(100000).optional(),
  priceCents: z.coerce.number().int().min(0).max(100000000),
  termMonths: z.coerce.number().int().min(1).max(36),
  basePlanId: z.string().min(1),
  osTemplateId: z.string().optional(),
  sortOrder: z.coerce.number().int().min(0).max(100000),
});

/**
 * Create or update a GamePlan tier. ADMIN/BILLING only, audit-logged. Validates
 * the chosen base VPS Plan (sizing source) and the game OsTemplate (must belong
 * to the same game family, if provided).
 */
export async function adminSaveGamePlan(prev: Result | undefined, formData: FormData): Promise<Result> {
  const admin = await requireArea("billing");

  const rawSlots = String(formData.get("slots") ?? "").trim();
  const rawOs = String(formData.get("osTemplateId") ?? "").trim();
  const parsed = planSchema.safeParse({
    id: formData.get("id") || undefined,
    gameFamily: formData.get("gameFamily"),
    name: formData.get("name"),
    ramMB: formData.get("ramMB"),
    cpuCores: formData.get("cpuCores"),
    diskGB: formData.get("diskGB"),
    slots: rawSlots === "" ? undefined : rawSlots,
    priceCents: formData.get("priceCents"),
    termMonths: formData.get("termMonths"),
    basePlanId: formData.get("basePlanId"),
    osTemplateId: rawOs === "" ? undefined : rawOs,
    sortOrder: formData.get("sortOrder") ?? 0,
  });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Check the tier values." };
  }

